def pickle_load(content=None, file_obj=None, safe_to_import=None):
    if content is None and file_obj is None:
        raise ValueError("Either content or file_obj must be provided")

    if content is not None and file_obj is not None:
        raise ValueError("Only one of content or file_obj should be provided")

    if file_obj is not None:
        if isinstance(file_obj, io.TextIOWrapper):
            raise ValueError("Binary mode needed. Please open the file in binary mode.")
        content = file_obj.read()

    if isinstance(content, str):
        # Check if it's a pickle string
        if content.startswith('DeepDiff Delta Payload v0-0-1'):
            # This is a delta payload, not a pickle
            raise ValueError("This appears to be a Delta payload, not a pickle")
        # Try to unpickle as bytes
        try:
            content = content.encode('latin1')  # Handle string content that might be bytes
        except AttributeError:
            pass

    if isinstance(content, bytes):
        try:
            return _RestrictedUnpickler(io.BytesIO(content), safe_to_import=safe_to_import).load()
        except Exception as e:
            # If it fails, try to decode as latin1 first
            try:
                content = content.decode('latin1')
                return _RestrictedUnpickler(io.BytesIO(content.encode('latin1')), safe_to_import=safe_to_import).load()
            except Exception:
                raise e
    else:
        # If content is not bytes, try to read it as a file-like object
        if hasattr(content, 'read'):
            return _RestrictedUnpickler(content, safe_to_import=safe_to_import).load()
        else:
            raise TypeError("Content must be bytes or a file-like object")
